import React, { createContext, useContext, useEffect, useMemo, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import Icon from './icons.jsx';
import dealAllIcon from './assets/icons/deal-all.svg';
import dealSaleIcon from './assets/icons/deal-sale.svg';
import dealRentIcon from './assets/icons/deal-rent.svg';
import auctionHouseOne from './assets/auction-house.jpg';
import auctionHouseTwo from './assets/auction-house-02.jpg';
import auctionHouseThree from './assets/auction-house-03.jpg';
import { UZ_LOCATIONS, locationNames, placesForRegion, placeLabel } from './locations.js';
import './styles.css';
import './app.css';
import { api } from './api-client.js';
import { getLanguage, setLanguage, watchTranslations } from './i18n.js';


const MAP_TILE_URL=import.meta.env.VITE_MAP_TILE_URL||'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png';
const localeCode=()=>({uz:'uz-UZ',ru:'ru-RU',en:'en-GB',hi:'hi-IN',zh:'zh-CN',tr:'tr-TR',ko:'ko-KR'}[getLanguage()]||'uz-UZ');
const cash=n=>`${Number(n||0).toLocaleString(localeCode())} so‘m`;
const humanType={apartment:'Kvartira',house:'Hovli uy',land:'Yer',commercial:'Tijorat'};
const humanDeal={sale:'Sotuv',rent:'Ijara'};
const FavoritesContext=createContext({favoriteIds:new Set(),setFavoriteIds:()=>{},userId:null});
const propertyHref=id=>`#/property/${id}`;
function rememberPropertyView(property){try{const key='uyjoyla-recently-viewed',current=JSON.parse(localStorage.getItem(key)||'[]'),next=[property,...current.filter(item=>String(item.id)!==String(property.id))].slice(0,12);localStorage.setItem(key,JSON.stringify(next))}catch{}}
const getRoute=()=>decodeURI(location.hash.replace(/^#\/?/,''));
function normalizeUzPhone(value){let digits=String(value||'').replace(/\D/g,'');if(digits.startsWith('998'))digits=digits.slice(3);return digits.length===9?`+998${digits}`:''}
function formatUzPhone(value){let digits=String(value||'').replace(/\D/g,'');if(digits.startsWith('998'))digits=digits.slice(3);digits=digits.slice(0,9);if(!digits)return '';const groups=[digits.slice(0,2),digits.slice(2,5),digits.slice(5,7),digits.slice(7,9)].filter(Boolean);return `+998-${groups.join('-')}`}
function locationHeading(user){const district=String(user?.district||'').trim(),region=String(user?.region||'').trim(),raw=district||region;if(!raw)return 'Sizga yaqin e’lonlar';let name=raw.replace(/\s+(viloyati|shahri|tumani)$/iu,'').trim();if(/viloyati$/iu.test(raw))return `${name} viloyatida`;if(/qoraqalpog‘iston/iu.test(name))return `${name}da`;const last=Array.from(name).at(-1)?.toLocaleLowerCase('uz-UZ');return `${name}${last==='k'?'ka':last==='q'?'qa':'da'}`}

function App(){
  const [route,setRoute]=useState(getRoute());
  const [language,setCurrentLanguage]=useState(getLanguage());
  const [user,setUser]=useState(null),[boot,setBoot]=useState(false);
  const [favoriteIds,setFavoriteIds]=useState(()=>new Set());
  const [notice,setNotice]=useState(''),[error,setError]=useState('');
  const [authOpen,setAuthOpen]=useState(false),[authStep,setAuthStep]=useState('phone'),[challenge,setChallenge]=useState(''),[phone,setPhone]=useState(''),[busy,setBusy]=useState(false);
  const [query,setQuery]=useState(()=>new URLSearchParams(location.hash.split('?')[1]||'').get('q')||'');
  const [featured,setFeatured]=useState([]);
  const [feedbackKind,setFeedbackKind]=useState(''),[feedbackPrompt,setFeedbackPrompt]=useState(false);
  const [languageModalOpen,setLanguageModalOpen]=useState(false);
  useEffect(()=>{const change=()=>{const nextRoute=getRoute();setRoute(nextRoute);if(nextRoute.startsWith('home?'))setQuery(new URLSearchParams(nextRoute.split('?')[1]||'').get('q')||'');setError('');window.scrollTo(0,0)};window.addEventListener('hashchange',change);return()=>window.removeEventListener('hashchange',change)},[]);
  useEffect(()=>watchTranslations(),[]);
  useEffect(()=>{const change=e=>setCurrentLanguage(e.detail||getLanguage());window.addEventListener('euylar:language',change);return()=>window.removeEventListener('euylar:language',change)},[]);
  useEffect(()=>{api('/bootstrap').then(d=>{setUser(d.user);setFavoriteIds(new Set(d.favorites||[]))}).catch(e=>setError(e.message)).finally(()=>setBoot(true))},[]);
  useEffect(()=>{if(!user){setFavoriteIds(new Set());return}let cancelled=false;api('/me/favorites').then(d=>{if(!cancelled)setFavoriteIds(new Set((d.items||[]).map(item=>item.id)))}).catch(()=>{});return()=>{cancelled=true}},[user?.id]);
  useEffect(()=>{api('/properties?sort=new&page=1&pageSize=8').then(d=>setFeatured(d.items)).catch(e=>setError(e.message))},[]);
  useEffect(()=>{if(notice){const id=setTimeout(()=>setNotice(''),4000);return()=>clearTimeout(id)}},[notice]);
  useEffect(()=>{if(sessionStorage.getItem('uyjoyla-feedback-prompt'))return;const id=setTimeout(()=>{sessionStorage.setItem('uyjoyla-feedback-prompt','shown');setFeedbackPrompt(true)},20000);return()=>clearTimeout(id)},[]);
  useEffect(()=>{if(!feedbackKind&&!feedbackPrompt)return;const close=e=>{if(e.key==='Escape'){setFeedbackKind('');setFeedbackPrompt(false)}};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close)},[feedbackKind,feedbackPrompt]);
  async function sendCode(e){e.preventDefault();const normalized=normalizeUzPhone(phone);if(!normalized){setError('Telefon raqamini +998-XX-XXX-XX-XX shaklida to‘liq kiriting.');return}setBusy(true);setError('');try{const d=await api('/auth/otp',{method:'POST',body:{phone:normalized}});setChallenge(d.challengeId);setAuthStep('code');setNotice('Tasdiqlash kodi telefon raqamingizga yuborildi.')}catch(e){setError(e.message)}finally{setBusy(false)}}
  async function verifyCode(e){e.preventDefault();const normalized=normalizeUzPhone(phone);if(!normalized){setError('Telefon raqamini qayta tekshiring.');setAuthStep('phone');return}setBusy(true);setError('');const form=new FormData(e.currentTarget);try{const d=await api('/auth/verify',{method:'POST',body:{challengeId:challenge,phone:normalized,code:form.get('code'),name:form.get('name')}});setUser(d.user);setAuthOpen(false);setAuthStep('phone');setNotice('Tizimga kirdingiz.')}catch(e){setError(e.message)}finally{setBusy(false)}}
  async function logout(){try{await api('/auth/logout',{method:'POST'});setUser(null);setNotice('Tizimdan chiqdingiz.')}catch(e){setError(e.message)}}
  function requireUser(){if(!user){setAuthOpen(true);return false}return true}
  const page=useMemo(()=>{
    if(route.startsWith('property/'))return <PropertyPage id={route.split('/')[1]} user={user} requireUser={requireUser} setNotice={setNotice}/>;
    if(route==='home'||route.startsWith('home?')||!route)return <AuctionHomePage/>;
    if(route==='map')return <MapPage setNotice={setNotice}/>;
    if(route.startsWith('seller/'))return <SellerPage id={route.split('/')[1]} user={user} requireUser={requireUser} setNotice={setNotice}/>;
    if(route==='post')return <PostPage user={user} requireUser={requireUser} setNotice={setNotice}/>;
    if(route==='my-listings')return <MyListings user={user} requireUser={requireUser}/>;
    if(route==='favorites')return <Favorites user={user} requireUser={requireUser}/>;
    if(route.startsWith('messages'))return <Messages user={user} requireUser={requireUser}/>;
    if(route==='notifications')return <Notifications user={user} requireUser={requireUser}/>;
    if(route==='profile')return <Profile user={user} listings={featured} requireUser={requireUser} onFeedback={setFeedbackKind} onLanguage={()=>setLanguageModalOpen(true)}/>;
    if(route==='profile/edit')return <ProfileEdit user={user} requireUser={requireUser} setUser={setUser} setNotice={setNotice}/>;
    if(route==='help')return <ContactPage setNotice={setNotice} title="Yordam markazi" subtitle="Savolingiz yoki taklifingiz bo‘lsa, bizga yozing."/>;
    if(route==='terms')return <LegalPage privacy={false}/>;
    if(route==='privacy')return <LegalPage privacy/>;
    if(route==='compare')return <ComparePage/>;
    if(route==='saved-searches')return <SavedSearches user={user} requireUser={requireUser}/>;
    if(route==='projects')return <ProjectsPage/>;
    if(route==='auctions')return <AuctionsPage requireUser={requireUser} setNotice={setNotice}/>;
    if(route.startsWith('auction/'))return <AuctionDetail id={route.split('/')[1]} user={user} requireUser={requireUser} setNotice={setNotice}/>;
    if(route==='contact')return <ContactPage setNotice={setNotice}/>;
    if(route==='catalog'||route==='listings'||route.startsWith('listings?'))return <ListingsPage initialQuery={query} user={user} requireUser={requireUser} setNotice={setNotice}/>;
    return <AuctionHomePage/>;
  },[route,user,boot,featured,query,language]);
  return <FavoritesContext.Provider value={{favoriteIds,setFavoriteIds,userId:user?.id||null}}>
    <SiteHeader route={route} user={user} onLogin={()=>setAuthOpen(true)} onLogout={logout} query={query} setQuery={setQuery}/>
    {error&&<div className="global-error" role="alert"><span>{error}</span><button aria-label="Xabarni yopish" onClick={()=>setError('')}>×</button></div>}
    {notice&&<div className="toast" role="status">{notice}</div>}
    <div className="route-transition" key={route}>{page}</div>
    <MobileNav route={route}/>
    <SiteFooter/>
    {feedbackPrompt&&<div className="feedback-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)setFeedbackPrompt(false)}}><section className="feedback-modal feedback-prompt" role="dialog" aria-modal="true" aria-labelledby="feedback-prompt-title"><button className="feedback-close" aria-label="Yopish" onClick={()=>setFeedbackPrompt(false)}>×</button><span className="feedback-symbol"><Icon name="chat"/></span><h2 id="feedback-prompt-title">Saytni yaxshilashga taklifingiz bormi?</h2><p>Fikr va takliflaringizni yuboring — Uy Joyla’ni siz bilan birga yaxshilaymiz.</p><div className="feedback-actions"><button className="btn primary" onClick={()=>{setFeedbackPrompt(false);setFeedbackKind('suggestion')}}>Taklif yuborish</button><button className="btn outline" onClick={()=>setFeedbackPrompt(false)}>Keyinroq</button></div></section></div>}
    {feedbackKind&&<FeedbackDialog kind={feedbackKind} onClose={()=>setFeedbackKind('')} user={user} setNotice={setNotice}/>}
    {languageModalOpen&&<LanguageModal onClose={()=>setLanguageModalOpen(false)}/>}
    {authOpen&&<AuthDialog step={authStep} phone={phone} setPhone={setPhone} onSend={sendCode} onVerify={verifyCode} onClose={()=>setAuthOpen(false)} busy={busy} error={error} setStep={setAuthStep} setError={setError}/>}
  </FavoritesContext.Provider>;
}

const LANGUAGE_OPTIONS=[['uz','O‘zbekcha','🇺🇿'],['ru','Русский','🇷🇺'],['en','English','🇬🇧'],['hi','हिन्दी','🇮🇳'],['zh','中文','🇨🇳'],['tr','Türkçe','🇹🇷'],['ko','한국어','🇰🇷']];
function LanguageSelect({className='',showIcon=false}){const [language,setCurrent]=useState(getLanguage);useEffect(()=>{const change=e=>setCurrent(e.detail||getLanguage());window.addEventListener('euylar:language',change);return()=>window.removeEventListener('euylar:language',change)},[]);return <label className={`language-switcher ${className}`}>{showIcon&&<Icon name="globe" size={17}/>}<select aria-label="Til" value={language} onChange={e=>{setCurrent(e.target.value);setLanguage(e.target.value)}}>{LANGUAGE_OPTIONS.map(([code,name])=><option key={code} value={code}>{name}</option>)}</select></label>}
function LanguageModal({onClose}){const [language,setCurrent]=useState(getLanguage);useEffect(()=>{const close=e=>{if(e.key==='Escape')onClose()};window.addEventListener('keydown',close);return()=>window.removeEventListener('keydown',close)},[onClose]);return <div className="feedback-backdrop language-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className="feedback-modal language-modal" role="dialog" aria-modal="true" aria-labelledby="language-title"><button className="feedback-close" aria-label="Close" onClick={onClose}>×</button><span className="feedback-symbol"><Icon name="globe"/></span><h2 id="language-title">Til</h2><div className="language-choice-list">{LANGUAGE_OPTIONS.map(([code,name,flag])=><button type="button" key={code} className={language===code?'selected':''} onClick={()=>setCurrent(code)}><span>{flag}</span><strong>{name}</strong>{language===code&&<Icon name="check" size={18}/>}</button>)}</div><button className="btn primary language-apply" onClick={()=>{setLanguage(language);onClose()}}>Saqlash</button></section></div>}
function MobileNav({route}){const active=(part)=>route===part||(!route&&part==='');return <nav className="mobile-bottom-nav" aria-label="Asosiy navigatsiya"><a className={!route||route==='home'||route.startsWith('home?')?'active':''} href="#/home"><Icon name="auction"/><span>Auksion</span></a><a className={route.startsWith('listings')||route==='catalog'?'active':''} href="#/listings"><Icon name="search"/><span>Mulklar</span></a><a className={`mobile-add ${route==='post'?'active':''}`} href="#/post" aria-label="E’lon joylash"><Icon name="plus"/><span>E’lon</span></a><a className={route.startsWith('messages')?'active':''} href="#/messages"><Icon name="chat"/><span>Xabarlar</span></a><a className={['profile','profile/edit','my-listings','notifications','saved-searches'].includes(route)?'active':''} href="#/profile"><Icon name="user"/><span>Profil</span></a></nav>}

function SiteHeader({route='',user,onLogin,onLogout,query,setQuery}){const [menu,setMenu]=useState(false),menuRoot=useRef(null);const isListings=route.startsWith('listings')||route==='catalog'||route==='map',isHome=!route||route==='home'||route.startsWith('home?'),hasPageSearch=route==='catalog'||route==='listings'||route.startsWith('listings?'),showMobileSearch=isHome||isListings;const showBrand=true,hideMobileHeader=route.startsWith('messages')||route==='profile'||route==='profile/edit';const mobileTitle=route.startsWith('messages')?'Xabarlar':route==='profile'||route==='profile/edit'?'Profil':route==='favorites'?'Sevimlilar':route==='notifications'?'Bildirishnomalar':route==='my-listings'?'E’lonlarim':route==='auctions'?'Auksionlar':route.startsWith('auction/')?'Lot tafsilotlari':route==='projects'?'Yangi uylar':route==='post'?'E’lon joylash':route==='help'?'Yordam markazi':'Uy Joyla';useEffect(()=>setMenu(false),[route]);useEffect(()=>{if(!menu)return;const outside=e=>{if(!menuRoot.current?.contains(e.target))setMenu(false)},escape=e=>{if(e.key==='Escape')setMenu(false)};document.addEventListener('pointerdown',outside);document.addEventListener('keydown',escape);return()=>{document.removeEventListener('pointerdown',outside);document.removeEventListener('keydown',escape)}},[menu]);function search(e){e.preventDefault();location.hash=`#/listings?q=${encodeURIComponent(query)}`;setMenu(false)}return <>
  <div className={`topbar ${showBrand?'mobile-listing-header':''}`}><div className="container top-inner"><a className="brand" href="#/home" aria-label="Uy Joyla bosh sahifa"><span className="brand-mark"><Icon name="home" size={25}/></span>Uy Joyla<span className="brand-dot">.</span></a><div className="top-links"><a className="top-help-link" href="#/help"><Icon name="help" size={17}/>Yordam</a><LanguageSelect className="desktop-language" showIcon/><span className="divider"/></div><div className="mobile-header-actions"><button onClick={()=>location.hash='#/notifications'} aria-label="Bildirishnomalar"><Icon name="bell"/></button></div></div></div>
  <header ref={menuRoot} className={`header ${showBrand?'mobile-listing-header':''} ${hideMobileHeader?'mobile-page-shell':''}`}><div className={`container searchbar ${showMobileSearch?'market-searchbar':''}`}>{showMobileSearch?(isHome?null:<button className="mobile-location" type="button" onClick={()=>location.hash='#/map'}><Icon name="pin"/><span>{user?.region||'Hududingizni tanlang'}</span><Icon name="arrow"/></button>):<div className="mobile-page-heading">{mobileTitle}</div>}{!hasPageSearch&&<form className="searchbox" onSubmit={search}><input aria-label="Ko‘chmas mulk qidirish" placeholder="Uy, kvartira yoki hududni qidiring" value={query} onChange={e=>setQuery(e.target.value)}/><button className="primary" aria-label="Qidirish"><Icon name="search"/></button></form>}{!isHome&&<a className="btn dark header-post" href="#/post">E’lon joylash <Icon name="plus"/></a>}<button className="iconbtn mobile-menu" aria-label="Katalog" onClick={()=>setMenu(!menu)}><Icon name="menu"/></button></div><div className="desktop-nav-row container"><nav className="desktop-main-nav" aria-label="Asosiy navigatsiya"><button className={`desktop-nav-link ${isListings?'active':''}`} onClick={()=>setMenu(!menu)}><Icon name="menu"/><span>Katalog</span></button><a className={`desktop-nav-link ${route==='auctions'||route.startsWith('auction/')?'active':''}`} href="#/auctions"><Icon name="auction"/><span>Auksionlar</span></a><a className={`desktop-nav-link ${route==='favorites'?'active':''}`} href="#/favorites"><Icon name="heart"/><span>Sevimlilar</span></a><a className={`desktop-nav-link ${route==='my-listings'?'active':''}`} href="#/my-listings"><Icon name="listings"/><span>E’lonlarim</span></a><a className={`desktop-nav-link ${route.startsWith('messages')?'active':''}`} href="#/messages"><Icon name="chat"/><span>Xabarlar</span></a></nav><button className="desktop-account-link" onClick={user?()=>location.hash='#/profile':onLogin}><Icon name="user"/><span>{user?'Kabinet':'Kirish'}</span></button></div>
    {menu&&<nav className="catalog-pop catalog-category-grid" aria-label="Katalog bo‘limlari">{[['Kvartiralar','building','#/listings?type=apartment'],['Hovli uylar','house','#/listings?type=house'],['Yer uchastkalari','land','#/listings?type=land'],['Tijorat mulki','store','#/listings?type=commercial'],['Yangi uylar','projects','#/projects'],['Auksion lotlari','auction','#/auctions']].map(([label,icon,href])=><a className="catalog-category" href={href} key={href}><span className="listing-category-icon"><Icon name={icon}/></span><span><strong>{label}</strong><small>Ko‘rish →</small></span></a>)}</nav>}
  </header></>}

function SiteFooter(){return <footer id="footer"><div className="container footer-grid"><div><a className="brand" href="#/">Uy Joyla<span className="brand-dot">.</span></a><p>Yangi manzil sari birinchi qadamingiz.</p></div><div><strong>Ko‘chmas mulk</strong><a href="#/listings">Barcha e’lonlar</a><a href="#/projects">Yangi uylar</a><a href="#/auctions">Auksionlar</a></div><div><strong>Yordam</strong><a href="#/help">Yordam markazi</a><a href="#/terms">Foydalanish shartlari</a><a href="#/privacy">Maxfiylik</a></div><div><strong>Aloqa</strong><a href="#/contact">Murojaat yuborish</a><a href="#/notifications">Bildirishnomalar</a></div></div><div className="footer-bottom"><span>© 2026 Uy Joyla</span><span aria-hidden="true">·</span><span>Created by <a href="https://studiostartup.uz" target="_blank" rel="noopener noreferrer">studiostartup.uz</a></span></div></footer>}

function Page({children,title,subtitle,actions,className=''}){return <main className={`container page ${className}`}><div className="page-title"><div>{title&&<h1>{title}</h1>}{subtitle&&<p className="muted">{subtitle}</p>}</div>{actions}</div>{children}</main>}
function Empty({title,text,action,href}){return <div className="empty panel"><h3>{title}</h3><p className="muted">{text}</p>{action&&<a className="btn primary" href={href}>{action}</a>}</div>}
function LoadingState({label='Yuklanmoqda…'}){return <div className="loading-state" role="status" aria-live="polite"><span className="loading-spinner" aria-hidden="true"/><span>{label}</span></div>}
const auctionHousePhotos=[auctionHouseOne,auctionHouseTwo,auctionHouseThree];
function AuctionHomePage(){
  const [lots,setLots]=useState(null),[loadFailed,setLoadFailed]=useState(false),[loading,setLoading]=useState(false);
  const [houseIndex,setHouseIndex]=useState(0),[touchStart,setTouchStart]=useState(null);
  function showHouse(index){setHouseIndex((index+auctionHousePhotos.length)%auctionHousePhotos.length)}
  function moveHouse(direction){showHouse(houseIndex+direction)}
  useEffect(()=>{const timer=setInterval(()=>setHouseIndex(index=>(index+1)%auctionHousePhotos.length),4500);return()=>clearInterval(timer)},[]);
  async function loadLots(){setLoading(true);setLoadFailed(false);try{const data=await api('/lots');setLots(data.items||[])}catch{setLots([]);setLoadFailed(true)}finally{setLoading(false)}}
  useEffect(()=>{loadLots()},[]);
  return <main className="container page auction-home"><section className="auction-hero"><div className="auction-hero-copy"><span className="eyebrow">Uy Joyla · ko‘chmas mulk auksioni</span><h1>Uy-joyni auksionda toping.</h1><p>Ochiq lotlarni ko‘ring, shartlarini o‘rganing va qatnashish uchun ariza yuboring.</p><a className="btn auction-hero-button" href="#/auctions">Faol auksionlarni ko‘rish <span aria-hidden="true">→</span></a></div><div className="auction-house-carousel" role="region" aria-label="Hashamatli uylar rasmlari" onTouchStart={e=>setTouchStart(e.touches[0].clientX)} onTouchEnd={e=>{if(touchStart!==null){const delta=e.changedTouches[0].clientX-touchStart;if(Math.abs(delta)>35)moveHouse(delta<0?1:-1)}setTouchStart(null)}}>{auctionHousePhotos.map((photo,index)=>{const offset=(index-houseIndex+auctionHousePhotos.length)%auctionHousePhotos.length;const position=offset===2?-1:offset;return <button type="button" key={photo} className={`auction-house-slide ${position===0?'active':''}`} style={{transform:`translateX(calc(-50% + ${position*80}%))`}} onClick={()=>showHouse(index)} aria-label={`${index+1}-uy rasmini ko‘rsatish`} aria-pressed={position===0}><img src={photo} alt="Zamonaviy hashamatli uy" draggable="false"/></button>})}</div></section>
    <section className="section auction-home-list"><div className="home-feed-heading"><div><h2>Faol auksionlar</h2><p>Yangi lotlar va qatnashish muddatlari</p></div><a href="#/auctions">Barcha lotlar <span aria-hidden="true">›</span></a></div>
      {lots===null||loading?<LoadingState label="Lotlar yuklanmoqda…"/>:loadFailed?<div className="auction-load-error" role="status"><span>Lotlar vaqtincha yuklanmadi.</span><button className="text-link" onClick={loadLots}>Qayta yuklash</button></div>:lots.length?<div className="grid auction-home-grid">{lots.map(l=><article className="panel lot-card" key={l.id}><a className="lot-card-main" href={`#/auction/${l.id}`}><span className="badge orange">Faol lot</span><h2>{l.title}</h2><p>{[l.region,l.address].filter(Boolean).join(' · ')}</p><strong>{cash(l.starting_price)}</strong><p className="tiny muted">Yakun: {l.deadline?new Date(l.deadline).toLocaleString(localeCode()):'Ko‘rsatilmagan'}</p></a><a className="btn primary small" href={`#/auction/${l.id}`}>Lot tafsilotlari</a></article>)}</div>:<Empty title="Hozircha faol lot yo‘q" text="Yangi lotlar e’lon qilinganda shu yerda ko‘rinadi."/>}
    </section><section className="auction-how"><h2>Qatnashish qanday ishlaydi?</h2><div className="auction-steps"><article><b>01</b><strong>Lotni tanlang</strong><p>Narx, manzil va auksion muddatini solishtiring.</p></article><article><b>02</b><strong>Shartlarni tekshiring</strong><p>Rasmiy lot havolasi va hujjatlarni diqqat bilan ko‘ring.</p></article><article><b>03</b><strong>Ariza yuboring</strong><p>Hisobingiz orqali qatnashish arizasini qoldiring.</p></article></div></section><p className="auction-disclaimer">Ariza yuborish lot egasining rasmiy auksion tartibida qatnashish huquqini o‘z-o‘zidan bermaydi. Yakuniy shartlar lot hujjatlarida ko‘rsatiladi.</p></main>
}
function LocationSelects({region,district,onRegion,onDistrict,regionLabel='Viloyat / shahar'}){const places=placesForRegion(region);return <><label className="field"><span>{regionLabel}</span><select aria-label={regionLabel} value={region} onChange={e=>onRegion(e.target.value)}><option value="">Barcha hududlar</option>{locationNames.map(n=><option key={n} value={n}>{n}</option>)}</select></label><label className="field"><span>Tuman / shahar</span><select aria-label="Tuman yoki shahar" value={district} disabled={!region} onChange={e=>onDistrict(e.target.value)}><option value="">Barchasi</option>{places.map(n=><option key={n} value={n}>{placeLabel(n)}</option>)}</select></label></>}
