  useEffect(()=>{if(initialParams.has('search')){setQuery(initialParams.get('q')||'');loadFeed({q:initialParams.get('q')||'',type:initialParams.get('type')||'',deal:initialParams.get('deal')||'',sort:initialParams.get('sort')||'new',pageSize:8})}},[]);
